using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class ViewsSeven {
 public static string Main(){var rows=new List<string>();foreach(string scene in new[]{"DansBackyardReverse","LakeWoods"}){EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");Physics.SyncTransforms();var g=new GameObject("Temporary review",typeof(Camera));var cam=g.GetComponent<Camera>();cam.CopyFrom(Camera.main);cam.enabled=false;
void Shot(string name,Vector3 eye,Vector3 target){cam.fieldOfView=70;cam.transform.SetPositionAndRotation(eye,Quaternion.LookRotation(target-eye));var rt=new RenderTexture(1200,750,24);var prior=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1200,750,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1200,750),0,0);tex.Apply();File.WriteAllBytes("Docs/SevenCorrections/before-"+name+".png",tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=prior;rt.Release();Object.DestroyImmediate(tex);Object.DestroyImmediate(rt);}
if(scene.StartsWith("Dans")){var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title.StartsWith("Storm"));Shot("wedge",new(179,69,89),new(166,64,76));Shot("drain",b.At(40,out _)+Vector3.up*1.8f,b.At(55,out _)+Vector3.up*1.8f);var r=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title.StartsWith("Abandoned"));Shot("ridge",r.At(94,out _)+Vector3.up*1.8f,r.At(114,out _)+Vector3.up);Shot("jump",new(407,100,28),new(390,81,-1));foreach(var mf in Object.FindObjectsByType<MeshFilter>().Where(m=>m.sharedMesh&&m.GetComponent<Renderer>()&&m.GetComponent<Renderer>().bounds.Intersects(new Bounds(new(172.1f,66,86.2f),new(24,18,24))))){var v=mf.sharedMesh.vertices.Select(mf.transform.TransformPoint).Where(p=>Math.Abs(p.x-172.1)<12&&Math.Abs(p.z-86.2)<12).ToArray();if(v.Length>0)rows.Add(mf.name+" parent="+mf.transform.parent?.name+" verts="+v.Length+" minY="+v.Min(p=>p.y)+" maxY="+v.Max(p=>p.y));}}
else{var b=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Echo Cave");var mf=GameObject.Find("Echo Cave enclosed rock").GetComponent<MeshFilter>();rows.Add("cave stations="+mf.sharedMesh.vertices.Min(p=>b.Project(mf.transform.TransformPoint(p),out _))+"-"+mf.sharedMesh.vertices.Max(p=>b.Project(mf.transform.TransformPoint(p),out _)));rows.Add("cave first vertices="+string.Join(";",mf.sharedMesh.vertices.Take(18)));foreach(float s in new[]{80f,160f,270f})Shot("cave-"+s,b.At(s,out _)+Vector3.up*1.8f,b.At(s+22,out _)+Vector3.up*1.8f);}
Object.DestroyImmediate(g);}File.WriteAllLines("Docs/SevenCorrections/visible-objects.txt",rows);EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");return "Captured";}}
